    consequences: ['吐蕃成为青藏高原长期延续的政治主体。', '其与唐、南诏及中亚政权的外交和战争关系进入新阶段。', '雅砻与逻些分别对应吐蕃形成期不同阶段的政治中心参照；中心承接不等于618年已经完成高原全域统一。', '雅砻、逻些与唐蕃交涉对应不同阶段；中心承接和对外关系变化不能合并为618年已经完成的高原统一。', '前618—622年吐蕃处于早期整合阶段；同期唐建国事件不构成吐蕃边界证据。', '吐蕃早期高原整合与唐蕃交涉分属连续阶段，618年约年不能代表后续高原范围已经稳定形成。'],
