    consequences: ['大理成为云南及周边延续数百年的区域政权。', '西南山地、东南亚与中原之间的交往网络重新组织。', '南诏之后的洱海地方网络由段氏王权继续承接，后续大理范围不能回填为937年的直接控制。', '大理早期以洱海核心和地方联盟承接南诏遗产；羊苴咩城政治中心与后期大理范围不是同一层次。', '段思平去世后的段氏承接仍需依靠地方联盟，不能把937年前后的建政约年或段思平个人活动延伸为后续大理全域的直接控制。', '1094—1096年高升泰建立大中国，1096年段氏复位；复位后的段氏王权与高氏相国权力不能合并为937年的建政节点。'],
